        assert x.is_cuda, "Input must be on CUDA device"
        x = x.contiguous()
        weight = self.conv2d.weight.contiguous()

        has_bias_flag = 1 if self.conv2d.bias is not None else 0
        if self.conv2d.bias is not None:
            bias_tensor = self.conv2d.bias.contiguous()
        else:
            bias_tensor = self.zero_bias.to(device=x.device, dtype=x.dtype).contiguous()

        B, C, H, W = x.shape
        OC = self.conv2d.out_channels
        KH, KW = self.conv2d.kernel_size
        pad_h, pad_w = self.conv2d.padding
        dil_h, dil_w = self.conv2d.dilation
        stride_h, stride_w = self.conv2d.stride

        H_out = (H + 2 * pad_h - dil_h * (KH - 1) - 1) // stride_h + 1
        W_out = (W + 2 * pad_w - dil_w * (KW - 1) - 1) // stride_w + 1

        output = torch.empty((B, OC, H_out, W_out), dtype=x.dtype, device=x.device)

        N = B * OC * H_out * W_out
        block = (16, 16, 1)
        OC_BLOCK = 4
        oc_groups = OC // OC_BLOCK
        grid = ((W_out + block[0] - 1) // block[0], (H_out + block[1] - 1) // block[1], B * oc_groups)

        module = _get_ptx_module()
        module.launch(
            "conv2d_kernel",
            grid=grid,
            block=block,
            arguments=[x, weight, output, bias_tensor, i32(N), i32(has_bias_flag)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return output

